/**
 * DayView — Single-day timeline with 30-minute slots and current time indicator.
 */

import { format } from 'date-fns';
import { Cake, Bell, AlertCircle } from 'lucide-react';
import { type CalendarEvent } from '@/stores/useCalendarStore';

const SLOTS = Array.from({ length: 32 }, (_, i) => 6 + i * 0.5); // 6am to 10pm in 30-min increments

interface Props {
  events: CalendarEvent[];
  selectedDate: string;
  onEventClick: (id: string) => void;
}

const STATUS_BG: Record<string, string> = {
  session: 'bg-blue-500',
  assessment: 'bg-purple-500',
  'follow-up': 'bg-amber-500',
  personal: 'bg-gray-500',
};



export default function DayView({ events, selectedDate, onEventClick }: Props) {
  const dayEvents = events.filter((e) => e.date === selectedDate);
  const now = new Date();
  const isToday = selectedDate === format(now, 'yyyy-MM-dd');
  const currentMinutes = isToday ? now.getHours() * 60 + now.getMinutes() : -1;

  const getEventPosition = (event: CalendarEvent) => {
    const startHour = parseInt(event.startTime.split(':')[0]);
    const startMin = parseInt(event.startTime.split(':')[1] || '0');
    const endHour = parseInt(event.endTime.split(':')[0]);
    const endMin = parseInt(event.endTime.split(':')[1] || '0');
    const startSlot = (startHour - 6) * 2 + (startMin >= 30 ? 1 : 0);
    const durationSlots = (endHour - startHour) * 2 + ((endMin - startMin) >= 30 ? 1 : 0);
    return { startSlot, durationSlots };
  };

  /* Determine background class for event */
  const getEventBgClass = (ev: CalendarEvent): string => {
    if (ev.type === 'unavailable') return 'bg-gray-400 dark:bg-gray-600';
    if (ev.type === 'event') return 'bg-purple-500';
    if (ev.type === 'birthday') return 'bg-pink-500';
    if (ev.type === 'reminder') return 'bg-amber-500';
    if (ev.type === 'todo') return 'bg-emerald-500';
    /* legacy types */
    if (typeof ev.type === 'string' && STATUS_BG[ev.type]) return STATUS_BG[ev.type];
    return 'bg-blue-500';
  };

  /* Get striped background for unavailable */
  const getEventStyle = (ev: CalendarEvent): React.CSSProperties => {
    if (ev.type === 'unavailable') {
      return {
        backgroundImage: 'repeating-linear-gradient(45deg, transparent, transparent 5px, rgba(255,255,255,0.1) 5px, rgba(255,255,255,0.1) 10px)',
      };
    }
    return {};
  };

  /* Render event label/icon prefix */
  const renderEventPrefix = (ev: CalendarEvent) => {
    if (ev.type === 'birthday') return <Cake className="w-3.5 h-3.5 mr-1 inline" />;
    if (ev.type === 'reminder') return <Bell className="w-3.5 h-3.5 mr-1 inline" />;
    if (ev.type === 'unavailable') return <AlertCircle className="w-3.5 h-3.5 mr-1 inline" />;
    return null;
  };

  return (
    <div className="relative border border-gray-200 dark:border-white/10 rounded-xl overflow-hidden">
      {isToday && currentMinutes >= 6 * 60 && (
        <div
          className="absolute left-16 right-0 z-10 pointer-events-none"
          style={{ top: `${(currentMinutes - 6 * 60) * 2 + 40}px` }}
        >
          <div className="flex items-center gap-2">
            <div className="w-2 h-2 rounded-full bg-red-500" />
            <div className="flex-1 h-px bg-red-500" />
          </div>
        </div>
      )}

      <div className="divide-y divide-gray-100 dark:divide-white/5">
        {SLOTS.map((slot, idx) => {
          const hour = Math.floor(slot);
          const min = (slot % 1) * 60;
          const slotEvents = dayEvents.filter((e) => {
            const { startSlot, durationSlots } = getEventPosition(e);
            return idx >= startSlot && idx < startSlot + durationSlots;
          });

          return (
            <div key={idx} className="grid grid-cols-[80px_1fr] min-h-[40px]">
              <div className="p-2 text-xs text-gray-400 border-r border-gray-100 dark:border-white/5 text-right pr-3">
                {min === 0 ? `${hour}:00` : ''}
              </div>
              <div className="p-1 relative">
                {slotEvents.map((ev, eIdx) => {
                  if (eIdx > 0) return null; // Only show on first slot
                  const { durationSlots } = getEventPosition(ev);
                  return (
                    <div
                      key={ev.id}
                      onClick={() => onEventClick(ev.id)}
                      className={`absolute inset-x-1 rounded-lg px-3 py-2 cursor-pointer hover:opacity-90 text-white text-xs font-medium shadow-sm z-10 ${getEventBgClass(ev)}`}
                      style={{ height: `${durationSlots * 40 - 4}px`, ...getEventStyle(ev) }}
                    >
                      <p className="font-semibold flex items-center">
                        {renderEventPrefix(ev)}
                        {ev.title}
                      </p>
                      <p className="opacity-80">{ev.startTime} - {ev.endTime}</p>
                    </div>
                  );
                })}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}
