/**
 * WeekView — 7-day time grid with draggable event blocks.
 */

import { useState } from 'react';
import { format, startOfWeek, addDays, parseISO } from 'date-fns';
import { Cake, Bell, AlertCircle } from 'lucide-react';
import { type CalendarEvent } from '@/stores/useCalendarStore';
import { useCalendarStore } from '@/stores/useCalendarStore';

const HOURS = Array.from({ length: 15 }, (_, i) => i + 7); // 7am - 9pm

const EVENT_BG: Record<string, string> = {
  confirmed: 'bg-blue-400',
  pending: 'bg-yellow-400',
  cancelled: 'bg-red-400',
  completed: 'bg-emerald-400',
  blocked: 'bg-gray-400',
};

const EVENT_TYPE_STYLES: Record<string, { bg: string; text: string; border?: string; icon?: typeof Cake }> = {
  unavailable: { bg: 'bg-gray-200 dark:bg-gray-700', text: 'text-gray-600 dark:text-gray-300', border: 'border border-gray-300 dark:border-gray-600 dashed' },
  event: { bg: 'bg-purple-100 dark:bg-purple-900/30', text: 'text-purple-700 dark:text-purple-300' },
  birthday: { bg: 'bg-pink-100 dark:bg-pink-900/30', text: 'text-pink-700 dark:text-pink-300', icon: Cake },
  reminder: { bg: 'bg-amber-100 dark:bg-amber-900/30', text: 'text-amber-700 dark:text-amber-300', icon: Bell },
};

interface Props {
  events: CalendarEvent[];
  selectedDate: string;
  onEventClick: (id: string) => void;
}

export default function WeekView({ events, selectedDate, onEventClick }: Props) {
  const { moveEvent } = useCalendarStore();
  const [dragOver, setDragOver] = useState<string | null>(null);
  const weekStart = startOfWeek(parseISO(selectedDate), { weekStartsOn: 1 });
  const days = Array.from({ length: 7 }, (_, i) => addDays(weekStart, i));

  const getEventsForDayHour = (date: string, hour: number) =>
    events.filter((e) => {
      const startHour = parseInt(e.startTime.split(':')[0]);
      return e.date === date && startHour === hour;
    });

  const handleDragStart = (e: React.DragEvent, eventId: string) => {
    e.dataTransfer.setData('eventId', eventId);
  };

  const handleDrop = (e: React.DragEvent, date: string, hour: number) => {
    e.preventDefault();
    const eventId = e.dataTransfer.getData('eventId');
    if (eventId) {
      const event = events.find((ev) => ev.id === eventId);
      if (event) {
        const newTime = `${hour.toString().padStart(2, '0')}:${event.startTime.split(':')[1] || '00'}`;
        moveEvent(eventId, date);
        useCalendarStore.getState().updateEvent(eventId, { startTime: newTime });
      }
    }
    setDragOver(null);
  };

  /* helper to determine event style based on type */
  const getEventClassName = (ev: CalendarEvent): string => {
    if (ev.type === 'unavailable') {
      return `${EVENT_TYPE_STYLES.unavailable.bg} ${EVENT_TYPE_STYLES.unavailable.text} ${EVENT_TYPE_STYLES.unavailable.border || ''} text-[11px] px-2 py-1 rounded mb-0.5 cursor-pointer hover:opacity-80 transition-opacity font-medium`;
    }
    if (ev.type === 'event') {
      return `${EVENT_TYPE_STYLES.event.bg} ${EVENT_TYPE_STYLES.event.text} text-[11px] px-2 py-1 rounded mb-0.5 cursor-pointer hover:opacity-80 transition-opacity font-medium`;
    }
    if (ev.type === 'birthday') {
      return `${EVENT_TYPE_STYLES.birthday.bg} ${EVENT_TYPE_STYLES.birthday.text} text-[11px] px-2 py-1 rounded mb-0.5 cursor-pointer hover:opacity-80 transition-opacity font-medium`;
    }
    if (ev.type === 'reminder') {
      return `${EVENT_TYPE_STYLES.reminder.bg} ${EVENT_TYPE_STYLES.reminder.text} text-[11px] px-2 py-1 rounded mb-0.5 cursor-pointer hover:opacity-80 transition-opacity font-medium`;
    }
    /* legacy session / assessment / follow-up / personal */
    return `${EVENT_BG[ev.title.includes('Cancel') ? 'cancelled' : ev.clientName ? 'confirmed' : 'completed'] || 'bg-gray-400'} text-white text-[11px] px-2 py-1 rounded mb-0.5 cursor-pointer hover:opacity-80 transition-opacity font-medium`;
  };

  /* helper to render event content */
  const renderEventContent = (ev: CalendarEvent) => {
    if (ev.type === 'birthday') {
      return (
        <span className="flex items-center gap-1">
          <Cake className="w-3 h-3 shrink-0" />
          {ev.title}
        </span>
      );
    }
    if (ev.type === 'reminder') {
      return (
        <span className="flex items-center gap-1">
          <Bell className="w-3 h-3 shrink-0" />
          {ev.title}
        </span>
      );
    }
    if (ev.type === 'unavailable') {
      return (
        <span className="flex items-center gap-1">
          <AlertCircle className="w-3 h-3 shrink-0" />
          {ev.title}
        </span>
      );
    }
    return ev.title;
  };

  return (
    <div className="border border-gray-200 dark:border-white/10 rounded-xl overflow-hidden">
      {/* Day Headers */}
      <div className="grid grid-cols-8 border-b border-gray-200 dark:border-white/10 bg-gray-50 dark:bg-[#1A1A1A]">
        <div className="p-3 text-xs font-medium text-gray-400">Time</div>
        {days.map((day) => {
          const isToday = format(day, 'yyyy-MM-dd') === format(new Date(), 'yyyy-MM-dd');
          return (
            <div key={day.toISOString()} className={`p-3 text-center ${isToday ? 'bg-[#00AEEF]/5' : ''}`}>
              <p className={`text-xs font-medium ${isToday ? 'text-[#00AEEF]' : 'text-gray-500 dark:text-gray-400'}`}>{format(day, 'EEE')}</p>
              <p className={`text-lg font-bold font-mono ${isToday ? 'text-[#00AEEF]' : 'text-gray-900 dark:text-white'}`}>{format(day, 'd')}</p>
            </div>
          );
        })}
      </div>

      {/* Time Grid */}
      <div className="divide-y divide-gray-100 dark:divide-white/5">
        {HOURS.map((hour) => (
          <div key={hour} className="grid grid-cols-8">
            <div className="p-2 text-xs text-gray-400 border-r border-gray-100 dark:border-white/5">{hour}:00</div>
            {days.map((day) => {
              const dateStr = format(day, 'yyyy-MM-dd');
              const dayEvents = getEventsForDayHour(dateStr, hour);
              const isDragOver = dragOver === `${dateStr}-${hour}`;
              return (
                <div
                  key={`${dateStr}-${hour}`}
                  onDragOver={(e) => { e.preventDefault(); setDragOver(`${dateStr}-${hour}`); }}
                  onDragLeave={() => setDragOver(null)}
                  onDrop={(e) => handleDrop(e, dateStr, hour)}
                  className={`p-1 min-h-[60px] border-r border-gray-100 dark:border-white/5 transition-colors ${
                    isDragOver ? 'bg-[#00AEEF]/10' : ''
                  }`}
                >
                  {dayEvents.map((ev) => (
                    <div
                      key={ev.id}
                      draggable
                      onDragStart={(e) => handleDragStart(e, ev.id)}
                      onClick={() => onEventClick(ev.id)}
                      className={getEventClassName(ev)}
                    >
                      {renderEventContent(ev)}
                    </div>
                  ))}
                </div>
              );
            })}
          </div>
        ))}
      </div>
    </div>
  );
}
