/**
 * MonthView — Standard month grid with event indicators.
 */

import { format, startOfMonth, endOfMonth, startOfWeek, endOfWeek, addDays, isSameMonth, isToday } from 'date-fns';
import { Cake, Bell } from 'lucide-react';
import { type CalendarEvent } from '@/stores/useCalendarStore';

interface Props {
  events: CalendarEvent[];
  selectedDate: string;
  onEventClick: (id: string) => void;
  onDayClick: (date: string) => void;
}

const STATUS_DOT: Record<string, string> = {
  confirmed: 'bg-blue-400',
  pending: 'bg-yellow-400',
  cancelled: 'bg-red-400',
  completed: 'bg-emerald-400',
};

const TYPE_DOT: Record<string, string> = {
  unavailable: 'bg-gray-400',
  event: 'bg-purple-400',
  birthday: 'bg-pink-400',
  reminder: 'bg-amber-400',
  todo: 'bg-emerald-400',
};

export default function MonthView({ events, selectedDate, onEventClick, onDayClick }: Props) {
  const monthStart = startOfMonth(new Date(selectedDate));
  const monthEnd = endOfMonth(monthStart);
  const calendarStart = startOfWeek(monthStart, { weekStartsOn: 1 });
  const calendarEnd = endOfWeek(monthEnd, { weekStartsOn: 1 });

  const days: Date[] = [];
  let day = calendarStart;
  while (day <= calendarEnd) {
    days.push(day);
    day = addDays(day, 1);
  }

  const getEventsForDay = (dateStr: string) => events.filter((e) => e.date === dateStr);
  const weekDays = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

  /* Get dot color based on event type */
  const getDotColor = (ev: CalendarEvent): string => {
    if (ev.type === 'session') return STATUS_DOT.confirmed || 'bg-blue-400';
    if (ev.type === 'assessment') return STATUS_DOT.pending || 'bg-yellow-400';
    if (ev.type === 'follow-up') return STATUS_DOT.completed || 'bg-emerald-400';
    if (ev.type === 'personal') return STATUS_DOT.cancelled || 'bg-red-400';
    return TYPE_DOT[ev.type] || 'bg-gray-300';
  };

  /* Check if day has special event types for icon display */
  const getDayIcons = (dayEvents: CalendarEvent[]) => {
    const icons: { type: string; count: number }[] = [];
    if (dayEvents.some((e) => e.type === 'birthday')) icons.push({ type: 'birthday', count: dayEvents.filter((e) => e.type === 'birthday').length });
    if (dayEvents.some((e) => e.type === 'reminder')) icons.push({ type: 'reminder', count: dayEvents.filter((e) => e.type === 'reminder').length });
    return icons;
  };

  return (
    <div className="border border-gray-200 dark:border-white/10 rounded-xl overflow-hidden">
      {/* Week Day Headers */}
      <div className="grid grid-cols-7 bg-gray-50 dark:bg-[#1A1A1A] border-b border-gray-200 dark:border-white/10">
        {weekDays.map((wd) => (
          <div key={wd} className="p-3 text-center text-xs font-medium text-gray-500 dark:text-gray-400">{wd}</div>
        ))}
      </div>

      {/* Day Grid */}
      <div className="grid grid-cols-7">
        {days.map((d) => {
          const dateStr = format(d, 'yyyy-MM-dd');
          const dayEvents = getEventsForDay(dateStr);
          const inMonth = isSameMonth(d, monthStart);
          const today = isToday(d);

          return (
            <div
              key={dateStr}
              onClick={() => onDayClick(dateStr)}
              className={`min-h-[100px] p-2 border-r border-b border-gray-100 dark:border-white/5 cursor-pointer hover:bg-gray-50 dark:hover:bg-[#1A1A1A] transition-colors ${
                !inMonth ? 'bg-gray-50/50 dark:bg-[#0A0A0A]' : ''
              } ${today ? 'ring-2 ring-[#00AEEF] ring-inset' : ''}`}
            >
              <div className="flex items-center justify-between">
                <p className={`text-sm font-medium font-mono ${today ? 'text-[#00AEEF]' : inMonth ? 'text-gray-900 dark:text-white' : 'text-gray-300 dark:text-gray-600'}`}>
                  {format(d, 'd')}
                </p>
                {/* Birthday / Reminder icons */}
                <div className="flex gap-0.5">
                  {getDayIcons(dayEvents).map((icon) => (
                    icon.type === 'birthday' ? (
                      <Cake key={icon.type} className="w-3 h-3 text-pink-400" />
                    ) : (
                      <Bell key={icon.type} className="w-3 h-3 text-amber-400" />
                    )
                  ))}
                </div>
              </div>
              <div className="mt-1 space-y-0.5">
                {dayEvents.slice(0, 3).map((ev) => (
                  <div
                    key={ev.id}
                    onClick={(e) => { e.stopPropagation(); onEventClick(ev.id); }}
                    className={`h-1.5 rounded-full ${getDotColor(ev)}`}
                  />
                ))}
                {dayEvents.length > 3 && (
                  <p className="text-[10px] text-gray-400">+{dayEvents.length - 3}</p>
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}
