/**
 * AgendaView — Chronological list of upcoming events.
 */

import { format, addDays, parseISO } from 'date-fns';
import { Clock, MapPin, User, Cake, Bell, AlertCircle, Calendar, CheckSquare } from 'lucide-react';
import { type CalendarEvent } from '@/stores/useCalendarStore';

interface Props {
  events: CalendarEvent[];
  selectedDate: string;
  onEventClick: (id: string) => void;
}

const STATUS_BADGE: Record<string, string> = {
  session: 'bg-blue-50 text-blue-700 dark:bg-blue-900/20 dark:text-blue-400',
  assessment: 'bg-purple-50 text-purple-700 dark:bg-purple-900/20 dark:text-purple-400',
  'follow-up': 'bg-amber-50 text-amber-700 dark:bg-amber-900/20 dark:text-amber-400',
  personal: 'bg-gray-50 text-gray-700 dark:bg-gray-800 dark:text-gray-400',
  unavailable: 'bg-gray-100 text-gray-600 dark:bg-gray-800 dark:text-gray-400',
  event: 'bg-purple-50 text-purple-700 dark:bg-purple-900/20 dark:text-purple-400',
  birthday: 'bg-pink-50 text-pink-700 dark:bg-pink-900/20 dark:text-pink-400',
  reminder: 'bg-amber-50 text-amber-700 dark:bg-amber-900/20 dark:text-amber-400',
  todo: 'bg-emerald-50 text-emerald-700 dark:bg-emerald-900/20 dark:text-emerald-400',
};



export default function AgendaView({ events, selectedDate, onEventClick }: Props) {
  const startDate = parseISO(selectedDate);
  const endDate = addDays(startDate, 30);

  const filtered = events
    .filter((e) => {
      const d = parseISO(e.date);
      return d >= startDate && d <= endDate;
    })
    .sort((a, b) => a.date.localeCompare(b.date) || a.startTime.localeCompare(b.startTime));

  // Group by date
  const grouped = filtered.reduce<Record<string, CalendarEvent[]>>((acc, ev) => {
    if (!acc[ev.date]) acc[ev.date] = [];
    acc[ev.date].push(ev);
    return acc;
  }, {});

  /* Get icon for event type */
  const getEventIcon = (ev: CalendarEvent) => {
    if (ev.type === 'birthday') return <Cake className="w-4 h-4 text-pink-400" />;
    if (ev.type === 'reminder') return <Bell className="w-4 h-4 text-amber-400" />;
    if (ev.type === 'unavailable') return <AlertCircle className="w-4 h-4 text-gray-400" />;
    if (ev.type === 'event') return <Calendar className="w-4 h-4 text-purple-400" />;
    if (ev.type === 'todo') return <CheckSquare className="w-4 h-4 text-emerald-400" />;
    return <User className="w-4 h-4 text-blue-400" />;
  };

  /* Get badge class for event type */
  const getBadgeClass = (ev: CalendarEvent): string => {
    return STATUS_BADGE[ev.type] || STATUS_BADGE.personal;
  };

  return (
    <div className="space-y-6">
      {Object.keys(grouped).length === 0 ? (
        <div className="text-center py-16 text-gray-400">
          <Clock className="w-12 h-12 mx-auto mb-3 opacity-30" />
          <p className="text-sm">No upcoming events in this period.</p>
        </div>
      ) : (
        Object.entries(grouped).map(([date, dayEvents]) => (
          <div key={date}>
            <h3 className="text-sm font-semibold text-gray-900 dark:text-white mb-3 sticky top-0 bg-white dark:bg-[#0A0A0A] py-2">
              {format(parseISO(date), 'EEEE, MMMM d')}
            </h3>
            <div className="space-y-2">
              {dayEvents.map((ev) => (
                <div
                  key={ev.id}
                  onClick={() => onEventClick(ev.id)}
                  className="flex items-center gap-4 bg-white dark:bg-[#141414] rounded-xl p-4 border border-gray-100 dark:border-white/5 cursor-pointer hover:border-[#00AEEF]/30 transition-colors"
                >
                  <div className="text-center min-w-[60px]">
                    <p className="text-lg font-bold text-[#00AEEF] font-mono">{ev.startTime}</p>
                    <p className="text-xs text-gray-400">{ev.endTime}</p>
                  </div>
                  <div className="flex items-center justify-center w-8 h-8 rounded-lg bg-gray-50 dark:bg-[#1A1A1A]">
                    {getEventIcon(ev)}
                  </div>
                  <div className="flex-1">
                    <div className="flex items-center gap-2 mb-1">
                      <p className="font-medium text-gray-900 dark:text-white">{ev.title}</p>
                      <span className={`text-[10px] px-2 py-0.5 rounded-full ${getBadgeClass(ev)}`}>{ev.type}</span>
                    </div>
                    <div className="flex items-center gap-3 text-xs text-gray-500">
                      {ev.clientName && <span className="flex items-center gap-1"><User className="w-3 h-3" />{ev.clientName}</span>}
                      <span className="flex items-center gap-1"><MapPin className="w-3 h-3" />AzTechFit</span>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        ))
      )}
    </div>
  );
}
