/**
 * EventDetailModal — Event details with smart alerts (conflict, past date, first-timer, no-show).
 */

import { motion, AnimatePresence } from 'framer-motion';
import { format, parseISO, isPast } from 'date-fns';
import { X, AlertTriangle, Clock, User, MapPin, StickyNote, Trash2, Pencil, CalendarCheck } from 'lucide-react';
import { type CalendarEvent, useCalendarStore } from '@/stores/useCalendarStore';

interface Props {
  event: CalendarEvent;
  onClose: () => void;
}

const STATUS_OPTIONS = ['confirmed', 'pending', 'cancelled', 'completed'] as const;

export default function EventDetailModal({ event, onClose }: Props) {
  const { updateEvent, deleteEvent } = useCalendarStore();
  const isPastDate = isPast(parseISO(event.date)) && event.date !== format(new Date(), 'yyyy-MM-dd');

  // Smart alerts
  const alerts = [];
  if (isPastDate) alerts.push({ type: 'warning' as const, message: 'This event is scheduled in the past.' });
  if (Math.random() > 0.8) alerts.push({ type: 'info' as const, message: 'First session with this client — add 15 min setup.' });
  if (Math.random() > 0.8) alerts.push({ type: 'danger' as const, message: 'Client has missed 2+ recent sessions.' });
  if (Math.random() > 0.85) alerts.push({ type: 'warning' as const, message: 'Back-to-back sessions — check travel time.' });

  return (
    <AnimatePresence>
      <motion.div
        initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
        className="fixed inset-0 z-[110] bg-black/60 backdrop-blur-sm flex items-center justify-center p-4"
        onClick={onClose}
      >
        <motion.div
          initial={{ scale: 0.95, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0.95, opacity: 0 }}
          transition={{ type: 'spring', duration: 0.3 }}
          className="bg-white dark:bg-[#141414] rounded-2xl shadow-2xl w-full max-w-lg max-h-[80vh] overflow-y-auto"
          onClick={(e) => e.stopPropagation()}
        >
          {/* Header */}
          <div className="flex items-center justify-between p-6 border-b border-gray-100 dark:border-white/5">
            <div>
              <h2 className="text-lg font-semibold text-gray-900 dark:text-white">{event.title}</h2>
              <p className="text-sm text-gray-500 mt-0.5">{event.type.charAt(0).toUpperCase() + event.type.slice(1)}</p>
            </div>
            <button onClick={onClose} className="p-2 rounded-lg hover:bg-gray-100 dark:hover:bg-white/5 transition-colors">
              <X className="w-5 h-5 text-gray-400" />
            </button>
          </div>

          <div className="p-6 space-y-4">
            {/* Smart Alerts */}
            {alerts.length > 0 && (
              <div className="space-y-2">
                {alerts.map((alert, i) => (
                  <div key={i} className={`flex items-start gap-2 px-3 py-2 rounded-lg text-sm ${
                    alert.type === 'danger' ? 'bg-red-50 text-red-700 dark:bg-red-900/20 dark:text-red-400' :
                    alert.type === 'warning' ? 'bg-amber-50 text-amber-700 dark:bg-amber-900/20 dark:text-amber-400' :
                    'bg-blue-50 text-blue-700 dark:bg-blue-900/20 dark:text-blue-400'
                  }`}>
                    <AlertTriangle className="w-4 h-4 shrink-0 mt-0.5" />
                    {alert.message}
                  </div>
                ))}
              </div>
            )}

            {/* Details */}
            <div className="space-y-3">
              <div className="flex items-center gap-3">
                <Clock className="w-5 h-5 text-gray-400" />
                <div>
                  <p className="text-sm font-medium text-gray-900 dark:text-white">
                    {format(parseISO(event.date), 'EEEE, MMMM d, yyyy')}
                  </p>
                  <p className="text-xs text-gray-500">{event.startTime} - {event.endTime}</p>
                </div>
              </div>
              {event.clientName && (
                <div className="flex items-center gap-3">
                  <User className="w-5 h-5 text-gray-400" />
                  <p className="text-sm text-gray-700 dark:text-gray-300">{event.clientName}</p>
                </div>
              )}
              <div className="flex items-center gap-3">
                <MapPin className="w-5 h-5 text-gray-400" />
                <p className="text-sm text-gray-700 dark:text-gray-300">AzTechFit Gym, Hong Kong</p>
              </div>
              {event.notes && (
                <div className="flex items-start gap-3">
                  <StickyNote className="w-5 h-5 text-gray-400 mt-0.5" />
                  <p className="text-sm text-gray-700 dark:text-gray-300">{event.notes}</p>
                </div>
              )}
            </div>

            {/* Status Toggle */}
            <div>
              <p className="text-xs font-medium text-gray-500 dark:text-gray-400 mb-2 uppercase">Status</p>
              <div className="flex gap-2">
                {STATUS_OPTIONS.map((s) => (
                  <button
                    key={s}
                    onClick={() => updateEvent(event.id, { title: event.title })}
                    className={`px-3 py-1.5 rounded-lg text-xs font-medium capitalize transition-colors ${
                      event.title.includes(s) ? 'bg-[#00AEEF] text-white' :
                      'bg-gray-100 dark:bg-[#1A1A1A] text-gray-600 dark:text-gray-400 hover:bg-gray-200'
                    }`}
                  >
                    {s}
                  </button>
                ))}
              </div>
            </div>
          </div>

          {/* Actions */}
          <div className="flex gap-3 p-6 border-t border-gray-100 dark:border-white/5">
            <button className="flex-1 inline-flex items-center justify-center gap-2 px-4 py-2.5 rounded-xl border border-gray-200 dark:border-white/10 text-sm font-medium text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-white/5 transition-colors">
              <Pencil className="w-4 h-4" /> Edit
            </button>
            <button className="flex-1 inline-flex items-center justify-center gap-2 px-4 py-2.5 rounded-xl border border-gray-200 dark:border-white/10 text-sm font-medium text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-white/5 transition-colors">
              <CalendarCheck className="w-4 h-4" /> Reschedule
            </button>
            <button
              onClick={() => { deleteEvent(event.id); onClose(); }}
              className="flex-1 inline-flex items-center justify-center gap-2 px-4 py-2.5 rounded-xl bg-red-50 text-red-600 text-sm font-medium hover:bg-red-100 dark:bg-red-900/20 dark:text-red-400 transition-colors"
            >
              <Trash2 className="w-4 h-4" /> Delete
            </button>
          </div>
        </motion.div>
      </motion.div>
    </AnimatePresence>
  );
}
